// @name Sliding puzzle
// @background #efece4
// @refresh 3600
// The 15 puzzle for a touch screen: tap a tile in the gap's row or column to
// slide it (and every tile between) into the gap, and put them back in
// order. 3x3, 4x4 or 5x5, with numbers or a picture cut into tiles. Every
// shuffle can be solved. The puzzle in progress and the best scores are kept.
import { shuffle, slide, isSolved } from './logic'
import { PICTURES, PictureDefs } from './pictures'
import { highContrast, canvasOf, Button, OptionsPage, Title, titleSize, textH, roundOf, RoundTable, RoundKey, RoundButton } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#efece4] text-[#22303a]',
    muted: 'text-[#5f6a72]',
    button: 'bg-[#dfd9cb] text-[#22303a] active:bg-[#d0c8b6]',
    primary: 'bg-[#2d3e4a] text-white active:bg-[#3d5262]',
    on: 'bg-[#2d3e4a] text-white',
    off: 'bg-[#dfd9cb] text-[#22303a]',
    board: '#2d3e4a',
    tile: '#f7f1e5',
    tileEdge: '#d9cfbb',
    number: '#2d3e4a',
    home: '#2a7f80',
    badge: '#2d3e4a',
    badgeText: '#ffffff',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    board: '#000000',
    tile: '#ffffff',
    tileEdge: '#000000',
    number: '#000000',
    home: '#000000',
    badge: '#000000',
    badgeText: '#ffffff',
  },
}

const settingsOf = (app) => {
  const n = Number(app.state.size)
  return {
    n: n === 3 || n === 5 ? n : 4,
    look: app.state.look === 'landscape' || app.state.look === 'rings' ? app.state.look : 'numbers',
  }
}

// The puzzle in progress, kept in the scene's private `game` field: the
// tiles row by row (0 the gap) and the tiles moved so far.
type Game = { n: number; tiles: number[]; moves: number; done?: boolean }
// What a tap changes is signals: the tile on each spot of the board and the
// status. A tap runs only the components that read them, not get().
const spots = Array.from({ length: 25 }, () => signal(0))
const solved = signal(false)
const gapAt = signal(-1)
const info = signal({ headline: '', detail: '' })
// The puzzle get() last loaded (a tap plays on it) and the best for its size.
let game: Game | null = null
let best = 0

const loadGame = (app): Game | null => {
  const g = app.state.game
  return g && Array.isArray(g.tiles) && g.tiles.length === g.n * g.n ? g : null
}
const save = (game: Game) => frameos.setState('game', game)
const newGame = (n: number): Game => ({ n, tiles: shuffle(n, Math.random), moves: 0 })

const bestOf = (app, n: number) => (app.state.best && typeof app.state.best === 'object' ? app.state.best[String(n)] : 0)

// The signals from the puzzle. A signal set to what it holds already wakes
// nothing.
const sync = (game: Game) => {
  game.tiles.forEach((tile, i) => {
    if (spots[i].peek() !== tile) spots[i].value = tile
  })
  const n = game.n
  const headline = game.done ? 'Solved!' : `${game.moves} ${game.moves === 1 ? 'move' : 'moves'}`
  const detail = game.done
    ? `In ${game.moves} moves${frameos.recall('record') ? ', a new best' : best ? `. Best: ${best}` : ''}`
    : best ? `Best for ${n} × ${n}: ${best}` : `${n} × ${n}: put the tiles in order`
  const now = info.peek()
  if (now.headline !== headline || now.detail !== detail) info.value = { headline, detail }
  if (solved.peek() !== !!game.done) solved.value = !!game.done
  const gap = game.tiles.indexOf(0)
  if (gapAt.peek() !== gap) gapAt.value = gap
}

const tapTile = (app, index: number) => {
  if (!game || game.done) return
  const tiles = game.tiles.slice()
  const moved = slide(tiles, game.n, index)
  if (!moved) return
  const next: Game = { n: game.n, tiles, moves: game.moves + moved }
  if (isSolved(tiles)) {
    next.done = true
    const all = app.state.best && typeof app.state.best === 'object' ? { ...app.state.best } : {}
    const key = String(game.n)
    frameos.remember('record', !all[key] || next.moves < all[key])
    if (!all[key] || next.moves < all[key]) {
      all[key] = next.moves
      frameos.setState('best', all)
    }
    best = all[key]
  }
  game = next
  save(next)
  sync(next)
}

const restart = (app) => {
  save(newGame(settingsOf(app).n))
  frameos.remember('page', null)
}

// Arrow keys slide the tile next to the gap that way; on frames with
// buttons, back leaves the options page and forward deals a new puzzle once
// this one is solved.
export function onEvent(app, context) {
  const event = context.event
  if (frameos.recall('page') === 'options') {
    if (event !== 'back') return false
    frameos.remember('page', null)
    return true
  }
  game = loadGame(app)
  if (!game) return false
  if (event === 'forward') {
    if (!game.done) return false
    restart(app)
    return true
  }
  if (event !== 'keyDown') return false
  const p = context.payload || {}
  if (p.ctrl || p.alt || p.meta) return false
  const n = game.n
  const gap = game.tiles.indexOf(0)
  const gr = Math.floor(gap / n)
  const gc = gap % n
  // The tile that moves is on the far side of the gap from the arrow.
  const from = { ArrowLeft: [gr, gc + 1], ArrowRight: [gr, gc - 1], ArrowUp: [gr + 1, gc], ArrowDown: [gr - 1, gc] }[p.key]
  if (from) {
    const [r, c] = from
    if (r >= 0 && r < n && c >= 0 && c < n) tapTile(app, r * n + c)
    return true
  }
  if (String(p.key).toLowerCase() === 'n') {
    restart(app)
    return true
  }
  return false
}

// Each picture is made once and drawn by every tile.
const pictures = {}
const pictureOf = (look, high) => {
  if (look === 'numbers') return null
  const key = `${look}${high ? ' high' : ''}`
  if (!pictures[key]) pictures[key] = PICTURES[look](high)
  return pictures[key]
}

// The board, 1000 units across, each tile a window onto its square of the
// picture or a number.
const Board = ({ t, n, look, high, size }) => {
  const picture = pictureOf(look, high)
  const parts = []
  for (let i = 0; i < n * n; i++) parts.push(<Spot t={t} n={n} i={i} look={look} high={high} />)
  return (
    <svg viewBox="-12 -12 1024 1024" width={size} height={size}>
      {picture && !high ? <PictureDefs /> : null}
      <rect x={-10} y={-10} width={1020} height={1020} rx={24} fill={t.board} />
      {parts}
    </svg>
  )
}

// What lies on spot `i` of the board: a tile, or the gap (nothing).
const Spot = memo(({ t, n, i, look, high }) => {
  const cell = 1000 / n
  const pad = cell * 0.04
  const done = solved.value
  let tile = spots[i].value
  const picture = pictureOf(look, high)
  // A solved picture is shown whole, the gap filled.
  if (!tile && done && picture) tile = n * n
  if (!tile) return <g />
  const x = (i % n) * cell + pad
  const y = Math.floor(i / n) * cell + pad
  const w = cell - pad * 2
  const home = tile - 1
  if (picture) {
    const hx = (home % n) * cell + pad
    const hy = Math.floor(home / n) * cell + pad
    const r = cell * 0.14
    return (
      <g>
        <svg x={x} y={y} width={w} height={w} viewBox={`${hx} ${hy} ${w} ${w}`}>{picture}</svg>
        {done ? null : <rect x={x + 2} y={y + 2} width={r * 2} height={r * 2} rx={r * 0.5} fill={t.badge} />}
        {done ? null : (
          <text x={x + 2 + r} y={y + 2 + r * 1.42} fontSize={r * 1.15} fontWeight="bold" textAnchor="middle" fill={t.badgeText}>
            {String(tile)}
          </text>
        )}
      </g>
    )
  }
  const atHome = home === i
  return (
    <g>
      <rect x={x} y={y} width={w} height={w} rx={cell * 0.1} fill={t.tile} stroke={t.tileEdge} strokeWidth={high ? 8 : 4} />
      <text x={x + w / 2} y={y + w / 2 + cell * 0.15} fontSize={cell * 0.42} fontWeight="bold" textAnchor="middle" fill={atHome ? t.home : t.number}>
        {String(tile)}
      </text>
    </g>
  )
})

// Each tile that can slide (in the gap's row or column) is an element of its
// own over the drawing: a tap slides it, and a frame's keys walk them (ringed)
// and OK slides one.
const Hit = memo(({ i, n, x, y, w, app }) => {
  const gap = gapAt.value
  const free = !solved.value && gap >= 0 && i !== gap && (Math.floor(i / n) === Math.floor(gap / n) || i % n === gap % n)
  return free
    ? <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${w}px] rounded-[${Math.round(w * 0.1)}px]`} onClick={() => tapTile(app, i)} />
    : <div className={`absolute left-[${x}px] top-[${y}px] w-[${w}px] h-[${w}px]`} />
})
const Hits = ({ n, size, app }) => {
  // Where a tile is in px: the board is 1024 units across from -12, a spot
  // 1000 / n of them, and a tile that less 4% of it each side.
  const at = (k: number) => Math.round(((12 + (k * 1000) / n + 40 / n) * size) / 1024)
  const w = Math.round(((920 / n) * size) / 1024)
  const hits = []
  for (let i = 0; i < n * n; i++) hits.push(<Hit i={i} n={n} x={at(i % n)} y={at(Math.floor(i / n))} w={w} app={app} />)
  return hits
}

// The moves, over the best for this size or how the puzzle was solved.
const Status = memo(({ ui, t }) => {
  const { headline, detail } = info.value
  return (
    <div className="flex flex-col">
      <span className={`text-[${ui.big}px] font-bold leading-tight`}>{headline}</span>
      <span className={`text-[${ui.small}px] ${t.muted}`}>{detail}</span>
    </div>
  )
})

// New puzzle, lit once this one is solved.
const NewButton = memo(({ ui, t, grow, onClick }) => (
  <Button ui={ui} grow={grow} className={solved.value ? t.primary : t.button} onClick={onClick}>New puzzle</Button>
))

// Round: the headline and its detail centred in the arc above the board.
const RoundStatus = memo(({ ui, t }) => {
  const { headline, detail } = info.value
  return (
    <div className="flex flex-col items-center">
      <span className={`text-[${ui.text}px] font-bold leading-tight`}>{headline}</span>
      <span className={`text-[${ui.small}px] ${t.muted}`}>{detail}</span>
    </div>
  )
})
const RoundNew = memo(({ room, ui, t, onClick }) => (
  <RoundButton room={room} ui={ui} className={solved.value ? t.primary : t.button} onClick={onClick}>New puzzle</RoundButton>
))

// The sizes kept as one object while they stay the same, and the app get()
// last ran with: what the memo()'d components are given stays equal.
let steady = null
const steadyUi = (ui) => (steady && Object.keys(ui).every((key) => ui[key] === steady[key]) ? steady : (steady = ui))
let lastApp = null
const restartLast = () => restart(lastApp)

export function get(app, context) {
  lastApp = app
  const ui = steadyUi(canvasOf(app, context))
  const high = highContrast(app)
  const t = high ? THEMES.high : THEMES.color
  const settings = settingsOf(app)
  const room = roundOf(context)

  if (frameos.recall('page') === 'options') {
    const rows = [
      { field: 'size', label: 'Size', value: String(settings.n), options: [['3', '3 × 3'], ['4', '4 × 4'], ['5', '5 × 5']] },
      { field: 'look', label: 'Tiles', value: settings.look, options: [['numbers', 'Numbers'], ['landscape', 'Landscape'], ['rings', 'Rings']] },
    ]
    return <OptionsPage ui={ui} t={t} title="Sliding puzzle" rows={rows} room={room}
      onClose={() => frameos.remember('page', null)} onNew={() => restart(app)} />
  }

  game = loadGame(app)
  if (!game || game.n !== settings.n) {
    game = newGame(settings.n)
    save(game)
  }
  const n = game.n
  best = bestOf(app, n)
  sync(game)

  // Side by side or stacked, whichever gives the bigger board.
  const sideW = Math.round(Math.max(ui.W * 0.27, ui.text * 9))
  const sideSize = Math.min(ui.W - sideW - ui.pad * 3, ui.H - ui.pad * 2)
  const stackSize = Math.min(ui.W - ui.pad * 2, ui.H - ui.pad * 2 - ui.gap * 2 - ui.button * 2)
  const side = sideSize >= stackSize
  const size = room ? room.side : Math.floor(side ? sideSize : stackSize)
  const board = (
    <div className={`relative w-[${size}px] h-[${size}px] shrink-0`}>
      <Board t={t} n={n} look={settings.look} high={high} size={size} />
      <Hits n={n} size={size} app={app} />
    </div>
  )

  const status = <Status ui={ui} t={t} />
  const buttons = [
    <NewButton ui={ui} t={t} grow={!side} onClick={restartLast} />,
    <Button ui={ui} grow={!side} className={t.button} onClick={() => frameos.remember('page', 'options')}>Options</Button>,
  ]

  if (room) {
    // Round: the board in the square inside the circle, the moves in the arc
    // above, Options beside it and a new puzzle below.
    return (
      <RoundTable room={room} t={t} board={board}
        top={<RoundStatus ui={ui} t={t} />}
        right={<RoundKey size={Math.min(56, room.x - 14)} t={t} icon="more" onClick={() => frameos.remember('page', 'options')} />}
        bottom={<RoundNew room={room} ui={ui} t={t} onClick={restartLast} />} />
    )
  }
  if (side) {
    // The column beside the board; where it is short (a 320x240 panel), the
    // name on one line.
    const colW = ui.W - ui.pad * 3 - size
    const named = titleSize(ui, colW, 'Sliding puzzle')
    const full = textH('Sliding puzzle', `text-[${named}px] font-bold leading-tight`, named, colW) + ui.big * 1.25 +
      textH(`${n} × ${n}: put the tiles in order`, `text-[${ui.small}px]`, ui.small, colW) + ui.button * 2 + ui.gap * 4
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        {board}
        <div className={`flex-1 h-full flex flex-col gap-[${ui.gap}px]`}>
          <Title ui={ui} width={colW} line={full > ui.H - ui.pad * 2}>Sliding puzzle</Title>
          {status}
          <div className="flex-1" />
          <div className={`space-y-[${ui.gap}px]`}>{buttons}</div>
        </div>
      </div>
    )
  }
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] items-center ${t.page}`}>
      {ui.H > ui.W * 1.3 ? <span className={`w-full text-[${ui.title}px] font-bold leading-tight`}>Sliding puzzle</span> : null}
      <div className={`flex items-center w-full h-[${ui.button}px]`}>{status}</div>
      <div className="flex-1 flex items-center justify-center">{board}</div>
      <div className={`flex w-full gap-[${ui.gap}px]`}>{buttons}</div>
    </div>
  )
}

