// The sliding puzzle's rules. Pure: no frameos calls, so it can be checked
// with plain node.
//
// A board is a list of n*n numbers read row by row, 1..n*n-1 for the tiles
// and 0 for the gap. Solved is 1, 2, 3, ... with the gap last.

export const solved = (n: number) => {
  const tiles: number[] = []
  for (let i = 1; i < n * n; i++) tiles.push(i)
  tiles.push(0)
  return tiles
}

export const isSolved = (tiles: number[]) => {
  for (let i = 0; i < tiles.length - 1; i++) if (tiles[i] !== i + 1) return false
  return true
}

// Whether a board can be solved: the count of pairs out of order, plus on an
// even width the gap's row counted from the bottom, must have the right parity.
export const solvable = (tiles: number[], n: number) => {
  let inversions = 0
  for (let i = 0; i < tiles.length; i++) {
    if (!tiles[i]) continue
    for (let j = i + 1; j < tiles.length; j++) if (tiles[j] && tiles[j] < tiles[i]) inversions++
  }
  if (n % 2 === 1) return inversions % 2 === 0
  const gapRowFromBottom = n - Math.floor(tiles.indexOf(0) / n)
  return (inversions + gapRowFromBottom) % 2 === 1
}

// A random board that can be solved and is not solved already: shuffle, and
// if the parity is wrong swap two tiles (which flips it).
export const shuffle = (n: number, random: () => number) => {
  for (;;) {
    const tiles = solved(n)
    for (let i = tiles.length - 1; i > 0; i--) {
      const j = Math.floor(random() * (i + 1))
      const swap = tiles[i]
      tiles[i] = tiles[j]
      tiles[j] = swap
    }
    if (!solvable(tiles, n)) {
      const a = tiles[0] && tiles[1] ? 0 : 2
      const b = tiles[0] && tiles[1] ? 1 : 3
      const swap = tiles[a]
      tiles[a] = tiles[b]
      tiles[b] = swap
    }
    if (!isSolved(tiles)) return tiles
  }
}

// Slides the tile at `index` towards the gap, with every tile between them,
// when it shares the gap's row or column. Answers the tiles moved (0 when
// it could not move), changing `tiles` in place.
export const slide = (tiles: number[], n: number, index: number) => {
  const gap = tiles.indexOf(0)
  if (index === gap || index < 0 || index >= tiles.length) return 0
  const gr = Math.floor(gap / n)
  const gc = gap % n
  const r = Math.floor(index / n)
  const c = index % n
  let step
  if (r === gr) step = c < gc ? -1 : 1
  else if (c === gc) step = r < gr ? -n : n
  else return 0
  // Walk from the gap to the tile, pulling each tile into the hole.
  let hole = gap
  let moved = 0
  while (hole !== index) {
    tiles[hole] = tiles[hole + step]
    hole += step
    moved++
  }
  tiles[index] = 0
  return moved
}

